const fs = require('node:fs/promises');
const path = require('node:path');

module.exports = async () => {
  const snapshotPath = path.join(__dirname, 'test_env_snapshot.txt');
  const systemPrompt = process.env.TEST_SYSTEM_PROMPT || '';

  await fs.writeFile(snapshotPath, systemPrompt, 'utf8');
};
